// lib/kids/builds/builds.ts
// Make It at Home (roadmap #44): kitchen-table robotics builds for homes and
// classrooms, rebuilt from the seven old printables (be the robot, balloon
// car, human line follower, sensor hunt, balancing bird, sorting robot,
// design a robot) and grown to cover every Skill Galaxy track and every World.
//
// Rules for authors (lib/kids/builds/verify.ts checks all of them, roadmap #79):
//   - every build has hazard tags, a minimum band and an adultRequired flag;
//   - a button or coin cell is NEVER in an Explorers build, and lithium packs
//     never below Inventors; mains power is never used, anywhere;
//   - materials must match the tags (scissors → blade, coin cell → button-cell…);
//   - `robodex` is a real card id; the fair test changes ONE thing;
//   - the check question can only be answered by someone who tried it;
//   - ids are stable forever (check-ins and portfolios are keyed by them).
// Facts must be true and checkable. Household materials only, nothing to buy
// beyond a few cheap parts for the electronics builds.
//
// Pure data: safe on the server and in the verify script. Client islands get
// what they need as props, never this whole file.

import type { BandId } from '../bands'
import type { Hazard, HazardInfo, HomeBuild } from './types'

export type { HomeBuild, Hazard, HazardInfo, FairTest, CheckQuestion } from './types'

export const HAZARDS: Record<Hazard, HazardInfo> = {
  none: { label: 'Nothing sharp, hot or small', icon: '✅', rule: 'Paper, card and household things only. A grown-up nearby is still a good idea.' },
  'small-parts': { label: 'Small parts', icon: '🔹', rule: 'Choking risk: keep beads, coins, caps, LEDs and clips away from babies and toddlers, and count them back in at the end.' },
  'button-cell': { label: 'Button / coin cell', icon: '🔘', rule: 'A swallowed button or coin cell can burn through the throat in about two hours. A grown-up holds the cell, fits it, and takes it away after. If one may have been swallowed, go to emergency care at once.' },
  'aa-battery': { label: 'AA batteries', icon: '🔋', rule: 'Use a battery holder. Never cut, heat or open a battery, and never join its two ends with a bare wire (it gets hot).' },
  'lithium-pack': { label: 'Lithium pack', icon: '⚠️', rule: 'Rechargeable lithium packs can catch fire if punctured, crushed or shorted. Grown-ups only.' },
  blade: { label: 'Scissors or blade', icon: '✂️', rule: 'Children use round-ended scissors. A grown-up does any cutting with a craft knife or snips, on a cutting board, away from fingers.' },
  'hot-glue': { label: 'Hot glue', icon: '🔥', rule: 'A grown-up uses the glue gun. The tip and fresh glue burn; tape works for most joints.' },
  'sharp-point': { label: 'Sharp points', icon: '📌', rule: 'Nails, skewers and pins are handled by a grown-up and pushed in away from hands.' },
  balloon: { label: 'Balloons or gloves', icon: '🎈', rule: 'Burst balloon pieces are a choking risk for young children: pick up every piece. Use non-latex if anyone has a latex allergy.' },
  water: { label: 'Water', icon: '💧', rule: 'Work on a tray or towel, away from plugs and devices, and wipe spills at once so nobody slips.' },
  'moving-body': { label: 'Moving around', icon: '🏃', rule: 'Clear a space first, walk slowly, and a grown-up spots anyone whose eyes are closed.' },
}

