export function getBuild(id: string): HomeBuild | undefined {
  return HOME_BUILDS.find((b) => b.id === id)
}

export const BAND_ORDER: readonly BandId[] = ['explorers', 'builders', 'inventors', 'engineers']

/** Builds a band can do (minBand at or below it). */
export function buildsForBand(band: BandId): HomeBuild[] {
  const i = BAND_ORDER.indexOf(band)
  return HOME_BUILDS.filter((b) => BAND_ORDER.indexOf(b.minBand) <= i)
}

/** The id reportActivity / reportBestRun uses for a home build (kind 'project'). */
export function buildRewardId(id: string): string {
  return `home-build-${id}`
}
